@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(244.3 100.0% 97.3%);
  --color-foreground: hsl(245.2 45.1% 20.0%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(245.2 45.1% 20.0%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(245.2 45.1% 20.0%);
  --color-primary: hsl(245.9 100.0% 67.8%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(241.7 81.4% 91.6%);
  --color-secondary-foreground: hsl(245.2 45.1% 20.0%);
  --color-muted: hsl(241.7 81.4% 91.6%);
  --color-muted-foreground: hsl(246.8 27.2% 61.8%);
  --color-accent: hsl(323.6 100.0% 94.5%);
  --color-accent-foreground: hsl(321.2 69.4% 38.4%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(243.8 69.6% 91.0%);
  --color-input: hsl(244.3 58.3% 85.9%);
  --color-ring: hsl(245.9 100.0% 67.8%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(244.3 100.0% 97.3%);
  --color-foreground: hsl(245.2 45.1% 20.0%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(245.2 45.1% 20.0%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(245.2 45.1% 20.0%);
  --color-primary: hsl(245.9 100.0% 67.8%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(241.7 81.4% 91.6%);
  --color-secondary-foreground: hsl(245.2 45.1% 20.0%);
  --color-muted: hsl(241.7 81.4% 91.6%);
  --color-muted-foreground: hsl(246.8 27.2% 61.8%);
  --color-accent: hsl(323.6 100.0% 94.5%);
  --color-accent-foreground: hsl(321.2 69.4% 38.4%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(243.8 69.6% 91.0%);
  --color-input: hsl(244.3 58.3% 85.9%);
  --color-ring: hsl(245.9 100.0% 67.8%);
    }

    @variant dark {
  --color-background: hsl(244.8 53.2% 9.2%);
  --color-foreground: hsl(244.0 100.0% 94.1%);
  --color-card: hsl(244.8 52.1% 23.7%);
  --color-card-foreground: hsl(244.0 100.0% 94.1%);
  --color-popover: hsl(244.5 55.6% 14.1%);
  --color-popover-foreground: hsl(244.0 100.0% 94.1%);
  --color-primary: hsl(246.6 100.0% 75.1%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(244.9 51.6% 18.6%);
  --color-secondary-foreground: hsl(244.0 100.0% 94.1%);
  --color-muted: hsl(244.9 51.6% 18.6%);
  --color-muted-foreground: hsl(246.2 32.4% 58.8%);
  --color-accent: hsl(278.2 34.7% 18.6%);
  --color-accent-foreground: hsl(320.5 100.0% 83.3%);
  --color-destructive: hsl(353.0 90.4% 59.2%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(244.8 52.1% 23.7%);
  --color-input: hsl(246.2 43.6% 30.6%);
  --color-ring: hsl(246.3 100.0% 81.2%);
    }
  }
}
